header = CardHeader("NVIDIA 데이터센터 사업 분석 (FY2026)", "NVIDIA 10-K, Fiscal Year Ended January 25, 2026")

sectionBlock = SectionBlock([
  SectionItem("overview", "개요 및 전략", [
    TextContent("NVIDIA의 FY2026 매출 증가는 주로 데이터센터 컴퓨팅 및 네트워킹 플랫폼에서 비롯되었습니다. Blackwell 아키텍처가 데이터센터 매출의 대다수를 차지하며 가속 컴퓨팅과 AI 수요가 크게 증가했습니다.", "default"),
    TextContent("NVIDIA는 GPU, CPU, DPU를 포함한 AI 서버용 프로세싱 유닛과 NVLink, 이더넷, 인피니밴드 등 고성능 데이터센터 네트워킹 솔루션을 제공합니다. 강력한 풀스택 소프트웨어와 결합된 전방위 가속 플랫폼 전략을 통해 AI 교육과 추론 작업에 집중하고 있습니다.", "default"),
    TextContent("또한, Rubin 플랫폼 출시로 대규모 장기 컨텍스트 워크플로우와 에이전트형 AI에 대한 지원을 준비하며, 제품 출시에는 다소 지연 및 공급망 관리 이슈를 경험하기도 했습니다.", "default"),
    TextContent("미국 정부 수출 제약 영향으로 인해 H20 제품군 관련 과잉 재고 및 구매 약정에 대해 $45억의 차감 충당금을 반영했으나, 일부 제품은 허가 하에 중국 시장에 소량 출하되었습니다.", "default"),
  ]),
  SectionItem("revenue_concentration", "매출 집중도 및 고객", [
    TextContent("직접 고객 중 한 곳이 전체 매출의 22%, 또 다른 고객이 14%에 해당하며, 모두 Compute & Networking 세그먼트에서 발생했습니다. 이는 데이터센터 사업 수요가 핵심임을 시사합니다.", "default"),
    TextContent("간접 고객 매출의 상당 부분도 클라우드 서비스 제공자 및 AI 연구 업체에서 발생하여 데이터센터 인프라 수요 증가를 뒷받침하고 있습니다.", "default"),
  ]),
  SectionItem("financials", "재무 사항 및 비용", [
    TextContent("데이터센터 사업 매출 증가는 NVIDIA 전체 매출 성장에 크게 기여했으며, 그 결과 FY2026 총매출은 $215.9B(약 266조원)로 전년 대비 65% 증가했습니다.", "default"),
    TextContent("총 이익률은 71.1%로 감소했는데, 이는 Blackwell 플랫폼 전환과 $45억 차감 충당금 영향 때문입니다. 연구 개발 비용도 43% 증가해 AI 및 컴퓨팅 인프라에 대한 투자가 확대되었음을 보여줍니다.", "default"),
  ])
